"""Demo-only About page; portraits and names supplied by the team."""
from pathlib import Path
import base64, re, html

BASE='/Imsfrane-demo/'
PEOPLE=[('farid-laydi','Farid Laydi','فريد العيدي'),('hamid-laydi','Hamid Laydi','حميد العيدي'),('ayoub-laydi','Ayoub Laydi','أيوب العيدي'),('abdelaziz-allam','Abdelaziz Allam','عبد العزيز علام'),('hassan-allam','Hassan Allam','حسن علام')]
COPY={
 'fr':dict(kicker='LES VISAGES DERRIÈRE L’AVENTURE',title='Notre équipe, l’esprit d’aventure.',intro='Nous partageons la même passion pour la nature et l’aventure. Randonnée en montagne, rafting ou VTT : notre équipe vous accompagne sur le terrain et prépare chaque séjour ensemble, du premier échange à l’accueil, en passant par le campement et les repas. Un travail collectif pour vous faire découvrir Imsfrane au plus près de ses habitants.',founder='Fondateur',manager='Responsable',company='Une aventure portée par une équipe locale et par Ichou Adventures, la société fondée par Farid Laydi.',see='Rencontrer notre équipe',skills=['Randonnée','Rafting','VTT']),
 'en':dict(kicker='THE PEOPLE BEHIND THE ADVENTURE',title='Our team, the spirit of adventure.',intro='We share a passion for nature and adventure. Whether hiking in the mountains, rafting or mountain biking, our team guides you outdoors and prepares each stay together, from the first conversation to welcoming you, setting up camp and preparing meals. We work as one team to help you discover Imsfrane and meet its people.',founder='Founder',manager='Manager',company='An adventure brought to life by a local team and Ichou Adventures, the company founded by Farid Laydi.',see='Meet our team',skills=['Hiking','Rafting','Mountain biking']),
 'es':dict(kicker='LAS PERSONAS DETRÁS DE LA AVENTURA',title='Nuestro equipo, el espíritu de aventura.',intro='Compartimos la pasión por la naturaleza y la aventura. Senderismo, rafting o BTT: nuestro equipo os acompaña y prepara cada estancia en conjunto, desde el primer contacto hasta la bienvenida, el campamento y las comidas. Trabajamos unidos para descubrir Imsfrane de cerca y conocer a su gente.',founder='Fundador',manager='Responsable',company='Una aventura impulsada por un equipo local e Ichou Adventures, la empresa fundada por Farid Laydi.',see='Conoce al equipo',skills=['Senderismo','Rafting','BTT']),
 'ar':dict(kicker='الناس وراء المغامرة',title='فريقنا، روح المغامرة.',intro='حنا فريق كيجمعنا شغف الطبيعة والمغامرة، وكنرافقو الزوار فالروندوني الجبلية، الرافتينغ وجولات VTT. كنتقاسمو تنظيم الرحلات واستقبال الضيوف وتجهيز المخيم والوجبات، وكنخدمو بروح واحدة باش تكون كل تجربة منظّمة، دافئة وقريبة من أهل المنطقة.',founder='المؤسس',manager='مسيّر',company='مبادرة بروح فريق محلي، إلى جانب شركة Ichou Adventures اللي أسّسها فريد العيدي.',see='تعرّف على فريقنا',skills=['الروندوني الجبلية','الرافتينغ','الدراجات الجبلية'])
}
CSS='''
main.team-about{background:#f7f5ef;color:#19382f;font:14px/1.8 Montserrat,Arial,sans-serif}main.team-about *{box-sizing:border-box}.team-about .wrap{width:min(1120px,calc(100% - 40px));margin:auto}.team-about .team-heading{max-width:850px}.team-about h1{font-family:'Cormorant Garamond',Georgia,serif;font-size:clamp(42px,5.5vw,70px);line-height:1.06;letter-spacing:-.025em;margin:15px 0 25px;color:#19382f}.team-about .team-section{padding-top:65px}.team-about .team-company{padding:25px 20px;border-block:1px solid #dddccd;margin-top:35px}.team-about .team-contact{text-align:center;margin-top:28px}.team-about .team-contact a{display:inline-block;background:#193f33;color:#fff;text-decoration:none;font-size:12px;font-weight:700;padding:13px 24px;border-radius:8px}html[dir=rtl] .team-about{font-family:inherit}html[dir=rtl] .team-about h1{font-family:inherit;line-height:1.65;font-size:clamp(32px,4.5vw,48px)}@media(max-width:700px){.team-about h1{font-size:40px}.team-about .team-contact a{width:100%}}

.team-about .team-section{padding:65px 0 70px;background:#f5f3ec;scroll-margin-top:90px}.team-about .team-heading{max-width:820px;margin-bottom:30px}.team-about .team-heading .tag{font-size:10px;letter-spacing:.14em;color:#927633}.team-about .team-heading h2{font-size:clamp(35px,4.3vw,54px);margin:12px 0 20px;color:#19382f}.team-about .team-heading p{font-size:14px;line-height:1.95;color:#536356;margin:0}.team-about .team-skills{display:flex;gap:9px;flex-wrap:wrap;margin:24px 0 0;padding:0;list-style:none}.team-about .team-skills li{padding:7px 14px;border:1px solid #d7ddce;border-radius:30px;font-size:11px;color:#3a5542;background:#fbfaf6}.team-about .people-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:28px 24px}.team-about .person-card{grid-column:span 2;min-width:0;background:#fff;border:1px solid #e1e3d9;border-radius:14px;overflow:hidden;box-shadow:0 8px 25px #19382f06}.team-about .person-card:nth-child(4){grid-column:2/span 2}.team-about .person-card:nth-child(5){grid-column:4/span 2}.team-about .person-portrait{aspect-ratio:4/5;overflow:hidden;background:#dbe6e7}.team-about .person-portrait img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 37%;transition:transform .35s ease}.team-about .person-card:first-child img{object-position:36% 40%}.team-about .person-info{padding:21px 22px 23px;border-top:3px solid #c6a43f}.team-about .person-info h3{font-family:Montserrat,Arial,sans-serif;font-size:18px;line-height:1.4;letter-spacing:-.025em;color:#19382f;margin:0 0 6px}.team-about .person-info p{font-size:12px;color:#7f692f;margin:0;line-height:1.6}.team-about .team-company{font-size:12px;line-height:1.9;color:#61705f;margin:27px 0 0;text-align:center}.team-about .hero{min-height:500px}.team-about .hero h1{font-size:clamp(52px,6vw,85px)}html[dir=rtl] .team-about .person-info h3{font-family:inherit;letter-spacing:0}html[dir=rtl] .team-about .team-heading h2{font-family:inherit;font-size:clamp(30px,4vw,43px);line-height:1.6}html[dir=rtl] .team-about .team-heading .tag{letter-spacing:0}
@media(max-width:700px){.team-about .team-section{padding:38px 0 44px}.team-about .team-heading{margin-bottom:24px}.team-about .team-heading h2{font-size:36px}.team-about .team-heading p{font-size:13px;line-height:1.95}.team-about .people-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px 12px}.team-about .person-card,.team-about .person-card:nth-child(4),.team-about .person-card:nth-child(5){grid-column:auto}.team-about .person-card:last-child{grid-column:1/-1;width:calc((100% - 12px)/2);justify-self:center}.team-about .person-info{padding:14px 11px 16px}.team-about .person-info h3{font-size:14px;min-height:40px;display:flex;align-items:center}.team-about .person-info p{font-size:11px}.team-about .team-company{text-align:start;font-size:11px}.team-about .hero{min-height:0}}
@media(prefers-reduced-motion:reduce){.team-about .person-portrait img{transition:none}}
'''

def build(root=Path('public')):
 target=root/'images'/'team';target.mkdir(parents=True,exist_ok=True)
 for slug,_,_ in PEOPLE:
  payload=Path('team-portraits',slug+'.webp.b64').read_text().strip()
  (target/(slug+'.webp')).write_bytes(base64.b64decode(payload,validate=True))
 (root/'about-team.css').write_text(CSS)
 for lang,c in COPY.items():
  path=root/lang/'about'/'index.html';source=path.read_text()
  cards=[]
  for n,(slug,latin,arabic) in enumerate(PEOPLE):
   name=arabic if lang=='ar' else latin;role=c['founder'] if n==0 else c['manager']
   cards.append(f'<article class="person-card"><div class="person-portrait"><img src="{BASE}images/team/{slug}.webp" alt="{html.escape(name)}" width="720" height="960" loading="lazy" decoding="async"></div><div class="person-info"><h3>{name}</h3><p>{role}</p></div></article>')
  contact={'fr':'Parlons de votre prochaine aventure','en':'Plan your next adventure with us','es':'Prepara tu próxima aventura','ar':'خلّينا نوجدو معاك المغامرة الجاية'}[lang]
  section=f'''<section class="team-section" id="our-team" aria-labelledby="team-title"><div class="wrap"><div class="team-heading"><div class="tag">{c['kicker']}</div><h1 id="team-title">{c['title']}</h1><p>{c['intro']}</p><ul class="team-skills">{''.join('<li>'+s+'</li>' for s in c['skills'])}</ul></div><div class="people-grid">{''.join(cards)}</div><p class="team-company">{c['company']}</p><div class="team-contact"><a href="{BASE}{lang}/contact/">{contact} ↗</a></div></div></section>'''
  # Replace the entire previous About body with the new team page.
  body='<main class="team-about" id="mainContent">'+section+'</main>'
  source,count=re.subn(r'<main\b.*?</main>',lambda m:body,source,count=1,flags=re.S)
  assert count==1,f'About main not found: {lang}'
  source=re.sub(r'<style\b[^>]*>.*?</style>',lambda m:'' if 'main.aboutx' in m[0] else m[0],source,flags=re.S)
  source=re.sub(r'<link[^>]*href="[^"]*about-team.css[^"]*"[^>]*>','',source)
  source=source.replace('</head>',f'<link rel="stylesheet" href="{BASE}about-team.css?v=team-page2"></head>',1)
  path.write_text(source)
 print('Built equal-sized cards for 5 team members × 4 languages.')

if __name__=='__main__':build()
